SELECT replaceRegexpOne(referer, concat('(?s)', '^https?://(?:www\\.)?([^/]+)/.*$'), '\\1'), avg(lengthUTF8(referer)), count(*), min(referer) FROM (SELECT * FROM streamed_table('/pgch_1715432_1_1_0', 'referer String')) WHERE ((referer <> '')) GROUP BY (replaceRegexpOne(referer, concat('(?s)', '^https?://(?:www\\.)?([^/]+)/.*$'), '\\1')) HAVING ((count(*) > 100000)) ORDER BY avg(lengthUTF8(referer)) DESC NULLS FIRST LIMIT 25
